);
CREATE TABLE trips (
    trip_id                   INTEGER PRIMARY KEY AUTOINCREMENT,

    -- ── Vendor ──────────────────────────────────────────────────────
    VendorID                  INTEGER,             -- 1=Creative Mobile, 2=VeriFone

    -- ── Timestamps ──────────────────────────────────────────────────
    tpep_pickup_datetime      TEXT NOT NULL,        -- Pickup date/time (ISO 8601)
    tpep_dropoff_datetime     TEXT NOT NULL,        -- Dropoff date/time (ISO 8601)

    -- ── Trip Details ────────────────────────────────────────────────
    passenger_count           INTEGER,             -- Number of passengers
    trip_distance             REAL,                -- Trip distance in miles
