    store_and_fwd_flag        TEXT,                -- Store-and-forward flag (Y/N)

    -- ── Location IDs ────────────────────────────────────────────────
    PULocationID              INTEGER,             -- Pickup TLC zone ID
    DOLocationID              INTEGER,             -- Dropoff TLC zone ID

    -- ── Payment ─────────────────────────────────────────────────────
    payment_type              INTEGER,             -- 1=Credit, 2=Cash, 3=No charge, etc.

    -- ── Financial ───────────────────────────────────────────────────
    fare_amount               REAL,                -- Base fare ($)
    extra                     REAL,                -- Misc extras and surcharges ($)
    mta_tax                   REAL,                -- MTA tax ($)
    tip_amount                REAL,                -- Tip amount ($)
    tolls_amount              REAL,                -- Tolls amount ($)
    improvement_surcharge     REAL,                -- Improvement surcharge ($)
    total_amount              REAL,                -- Total charged ($)
    congestion_surcharge      REAL,                -- Congestion surcharge ($)

    -- ── DERIVED FEATURES (engineered by Member A) ───────────────────
    trip_duration_minutes     REAL,                -- Duration in minutes (dropoff - pickup)
    avg_speed_mph             REAL,                -- Average speed (distance / duration)
    fare_per_mile             REAL,                -- Fare efficiency (fare / distance)

    -- ── TIME FEATURES (extracted by Member A) ───────────────────────
    pickup_hour               INTEGER,             -- Hour of pickup (0-23)
    pickup_day_of_week        INTEGER,             -- Day of week (0=Mon, 6=Sun)
    pickup_day_name           TEXT,                -- Day name (Monday-Sunday)
    pickup_month              INTEGER,             -- Month of pickup (1-12)

    -- ── DENORMALIZED LOCATION NAMES ─────────────────────────────────
    pickup_borough            TEXT,                -- Pickup borough name
    pickup_zone               TEXT,                -- Pickup zone/neighborhood
    dropoff_borough           TEXT,                -- Dropoff borough name
    dropoff_zone              TEXT,                -- Dropoff zone/neighborhood

    -- ── Foreign Keys ────────────────────────────────────────────────
    FOREIGN KEY (PULocationID) REFERENCES locations(location_id),
    FOREIGN KEY (DOLocationID) REFERENCES locations(location_id)
);
